(function(){
'use strict';
var Widget=require('$:/core/modules/widgets/widget.js').widget;
var E=require('$:/plugins/huwiki/cutout/engine.js');
function div(doc,cl){var e=doc.createElement('div');if(cl)e.className=cl;return e;}
function button(doc,label,fn){var b=doc.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',fn);return b;}
function readJson(wiki,title){try{return JSON.parse(wiki.getTiddlerText(title)||'null');}catch(e){return null;}}
function clamp(n,min,max){return Math.max(min,Math.min(max,n));}
function ease(t,e){return e==='step'?0:e==='linear'?t:t*t*(3-2*t);}
function motionValue(keys,time){
 if(!Array.isArray(keys)||!keys.length)return {dx:0,dy:0,rotate:0,scale:1,opacity:1};
 keys=keys.slice().sort(function(a,b){return Number(a.t)-Number(b.t);});
 var a=keys[0],b=keys[keys.length-1];
 if(time<=Number(a.t))b=a;
 else if(time>=Number(b.t))a=b;
 else for(var i=0;i<keys.length-1;i++)if(time>=Number(keys[i].t)&&time<=Number(keys[i+1].t)){a=keys[i];b=keys[i+1];break;}
 var f=a===b?0:clamp((time-Number(a.t))/(Number(b.t)-Number(a.t)),0,1);
 f=ease(f,b.easing||a.easing||'smooth');
 function get(k,def){var av=Number(a[k]),bv=Number(b[k]);if(!Number.isFinite(av))av=def;if(!Number.isFinite(bv))bv=av;return av+(bv-av)*f;}
 return {dx:get('dx',0),dy:get('dy',0),rotate:get('rotate',0),scale:get('scale',1),opacity:get('opacity',1)};
}
function Theatre(parseTreeNode,options){this.initialise(parseTreeNode,options);}
Theatre.prototype=new Widget();
Theatre.prototype.execute=function(){
 this.title=this.getAttribute('tiddler',this.getVariable('currentTiddler',''));
 this.movie=readJson(this.wiki,this.title);
 var ancestors=[],parent=this.parentWidget;while(parent){if(parent.title&&parent instanceof Theatre)ancestors.push(parent.title);parent=parent.parentWidget;}
 this.recursionBlocked=ancestors.indexOf(this.title)>=0||ancestors.length>=8;
 this.scenes=!this.recursionBlocked&&this.movie&&Array.isArray(this.movie.scenes)?this.movie.scenes.filter(function(s){return s&&(s.pasteup||s.animation||s.theatre)&&Number(s.duration)>0;}).map(function(s){return {pasteup:s.pasteup&&String(s.pasteup),animation:s.animation&&String(s.animation),theatre:s.theatre&&String(s.theatre),duration:Math.min(3600,Math.max(.1,Number(s.duration))),offset:E.finite(s.offset,0),speed:E.finite(s.speed,1),loop:!!s.loop,motion:String(s.motion||(s.pasteup?s.pasteup+'/Motion':''))};}):[];
 this.total=this.scenes.reduce(function(a,s){return a+s.duration;},0);
};
Theatre.prototype.makeLayer=function(scene,cls){
 var layer=div(this.document,'huw-theatre-scene '+(cls||''));
 layer.dataset.pasteupTitle=scene.pasteup;layer.setAttribute('data-cutout-clock','slave');
 var markup='\\import $:/plugins/huwiki/pasteup/Engine/Embed\n<$macrocall $name="pasteUpEmbed" tiddler="'+(scene.pasteup||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')+'" copy="no" tooltip="no" allowdrag="no" />';
 if(scene.animation||scene.theatre){var target=(scene.animation||scene.theatre).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');markup='<$'+(scene.animation?'cutout':'cutout-theatre')+' tiddler="'+target+'" controls="no" loop="'+(scene.loop?'yes':'no')+'"/>';}
 var parser=this.wiki.parseText('text/vnd.tiddlywiki',markup);
 var w=this.wiki.makeWidget(parser,{parentWidget:this,document:this.document});
 w.render(layer,null);layer._twWidget=w;
 layer._motion=readJson(this.wiki,scene.motion)||{};
 this.viewport.appendChild(layer);
 return layer;
};
Theatre.prototype.timeParts=function(t){
 var elapsed=clamp(t,0,this.total),start=0;
 for(var i=0;i<this.scenes.length;i++){
  var dur=this.scenes[i].duration;
  if(elapsed<start+dur || i===this.scenes.length-1)return {index:i,local:clamp(elapsed-start,0,dur),start:start};
  start+=dur;
 }
 return {index:0,local:0,start:0};
};
Theatre.prototype.applyMotion=function(layer,time){
 if(!layer||!layer.isConnected)return;
 var m=layer._motion||{};
 for(var field in m){if(!Object.prototype.hasOwnProperty.call(m,field))continue;
  var elems=layer.querySelectorAll('[data-pasteup-field]');
  for(var i=0;i<elems.length;i++){
   if(elems[i].getAttribute('data-pasteup-field')!==field)continue;
   var val=motionValue(m[field],time);
   elems[i].style.transform='translate('+val.dx+'%, '+val.dy+'%) rotate('+val.rotate+'deg) scale('+val.scale+')';
   elems[i].style.opacity=String(val.opacity);
  }
 }
 // The animation widget remains the owner of each SVG. Seek its player; the
 // stage simply supplies scene time, so nested objects never drift apart.
 var players=layer.querySelectorAll('.huw-cutout-player,.huw-theatre-player');
 for(var j=0;j<players.length;j++){
  if(players[j].parentElement.closest('.huw-theatre-player')!==this.host)continue;
  try{players[j].dispatchEvent(new CustomEvent('hu-theatre-seek',{detail:{time:time}}));}catch(err){}
 }
};
Theatre.prototype.showAt=function(time){
 if(!this.scenes.length)return;
 this.at=clamp(time,0,this.total);
 var next=this.timeParts(this.at);
 if(next.index!==this.activeIndex){
  // Keep the outer PasteUp frame in place: only replace the scene layer.
  if(this.activeLayer&&this.activeLayer.parentNode){this.applyMotion(this.activeLayer,0);if(this.activeLayer._twWidget)this.activeLayer._twWidget.removeChildDomNodes();this.viewport.removeChild(this.activeLayer);}
  this.activeIndex=next.index;
  this.activeLayer=this.makeLayer(this.scenes[next.index],'huw-theatre-current');
 }
 var clip=this.scenes[next.index];this.applyMotion(this.activeLayer,Math.max(0,next.local*clip.speed+clip.offset));
 if(this.seek)this.seek.value=String(this.at);
 if(this.readout)this.readout.textContent=this.at.toFixed(1)+' / '+this.total.toFixed(1)+' s · Scene '+(next.index+1)+'/'+this.scenes.length;
};
Theatre.prototype.play=function(on){
 if(on&&this.controlled)return;
 this.isPlaying=!!on;
 if(this.playButton)this.playButton.textContent=this.isPlaying?'Ⅱ Pause':coUi.t('▶ Afspil');
 if(!on){if(this.raf&&typeof cancelAnimationFrame==='function')cancelAnimationFrame(this.raf);this.raf=0;return;}
 if(this.at>=this.total)this.showAt(0);
 var self=this;this.last=0;
 function tick(now){
  if(!self.isPlaying)return;
  if(!self.host||!self.host.isConnected||self.document.hidden){self.play(false);return;}
  if(self.last)self.at+=(now-self.last)/1000;
  self.last=now;
  if(self.at>=self.total){self.showAt(self.total);self.play(false);return;}
  self.showAt(self.at);
  self.raf=requestAnimationFrame(tick);
 }
 this.raf=requestAnimationFrame(tick);
};
Theatre.prototype.render=function(parent,nextSibling){
 this.parentDomNode=parent;this.computeAttributes();this.execute();
 var doc=this.document,self=this,host=div(doc,'huw-theatre-player');this.host=host;this.controlled=!!(parent.closest&&parent.closest('[data-cutout-clock],.huw-theatre-player'));host.setAttribute('data-cutout-clock',this.controlled?'slave':'master');
 parent.insertBefore(host,nextSibling);this.domNodes.push(host);
 if(!this.scenes.length){host.textContent=coUi.t('Denne forestilling indeholder ingen gyldige scener: ')+this.title;return;}
 this.viewport=div(doc,'huw-theatre-stage');host.appendChild(this.viewport);
 host.addEventListener('hu-theatre-seek',function(evt){if(evt.target!==host||!evt.detail||!Number.isFinite(Number(evt.detail.time)))return;self.play(false);var t=Number(evt.detail.time);self.showAt(self.getAttribute('loop','no')==='yes'?E.localTime(t,self.total,{loop:true}):t);});
 var controls=div(doc,'huw-theatre-controls');if(this.controlled||this.getAttribute('controls','yes')==='no')controls.hidden=true;
 controls.appendChild(button(doc,coUi.t('Fuld skærm ↔'),function(){host.classList.toggle('huw-studio-fullscreen');}));
 this.playButton=button(doc,coUi.t('▶ Afspil'),function(){self.play(!self.isPlaying);});controls.appendChild(this.playButton);
 controls.appendChild(button(doc,'↺',function(){self.play(false);self.showAt(0);}));
 this.seek=doc.createElement('input');this.seek.type='range';this.seek.min='0';this.seek.max=String(this.total);this.seek.step='.05';this.seek.setAttribute('aria-label',coUi.t('Tidslinje for forestillingen'));this.seek.addEventListener('input',function(){self.play(false);self.showAt(Number(self.seek.value));});controls.appendChild(this.seek);
 this.readout=div(doc,'huw-theatre-readout');controls.appendChild(this.readout);host.appendChild(controls);
 var previous=coUi.previous(this,"theatre");this.at=0;this.activeIndex=-1;this.isPlaying=false;this.showAt(previous?previous.time:0);coUi.remember(this,"theatre");if(previous&&previous.playing)this.play(true);
};
Theatre.prototype.refresh=function(changed){if(changed["$:/language"]){coUi.capturePlayback(this);this.refreshSelf();return true;}
 var attrs=this.computeAttributes();
 if(attrs.tiddler||changed[this.title]){this.play(false);this.refreshSelf();return true;}
 if(this.activeLayer&&this.activeLayer._twWidget){
  if(changed[this.scenes[this.activeIndex].motion])this.activeLayer._motion=readJson(this.wiki,this.scenes[this.activeIndex].motion)||{};
  this.activeLayer._twWidget.refresh(changed);
 }
 return false;
};
var Player=require('$:/plugins/huwiki/cutout/widgets/player.js').cutout;
function Compatible(p,o){this.initialise(p,o);}Compatible.prototype=new Theatre();
Compatible.prototype.render=function(parent,next){this.computeAttributes();var title=this.getAttribute('tiddler',this.getVariable('currentTiddler')),data=readJson(this.wiki,title);this.modern=!!(data&&Array.isArray(data.scenes)&&data.scenes.every(function(s){return !s.pasteup;}));if(this.modern)Player.prototype.render.call(this,parent,next);else Theatre.prototype.render.call(this,parent,next);};
Compatible.prototype.refresh=function(changed){return this.modern?Player.prototype.refresh.call(this,changed):Theatre.prototype.refresh.call(this,changed);};
Compatible.prototype.removeChildDomNodes=function(){coUi.capturePlayback(this);if(this.modern){if(this.clock)this.clock.destroy();}else{this.play(false);if(this.activeLayer&&this.activeLayer._twWidget)this.activeLayer._twWidget.removeChildDomNodes();}Widget.prototype.removeChildDomNodes.call(this);};
exports['cutout-theatre']=Compatible;
})();
