.huw-theatre-player{box-sizing:border-box;display:flex;flex-direction:column;min-width:0;width:100%;height:100%;font-family:system-ui,sans-serif}
.huw-theatre-stage{position:relative;isolation:isolate;overflow:hidden;width:100%;min-height:1px;flex:1 1 auto;background:#dae8ef}
.huw-theatre-scene{width:100%;height:100%;position:relative;top:0;left:0;box-sizing:border-box;overflow:hidden}
.huw-theatre-scene>.tt-pasteup-layout{height:100%}
.huw-theatre-scene .tt-pasteup-layout{box-shadow:none!important;border:0!important}
.huw-theatre-controls{display:flex;align-items:center;gap:.4em;background:#172a40;color:#f7ebdb;padding:6px 7px;box-sizing:border-box;flex-wrap:wrap;font-size:clamp(10px,1.15vw,14px);line-height:1.2}
.huw-theatre-controls button{background:#f2c96b!important;border:0!important;border-radius:5px!important;color:#16253a!important;font-size:1em!important;padding:.4em .65em!important;cursor:pointer}
.huw-theatre-controls input[type=range]{flex:1 1 5em;min-width:3em;accent-color:#f3c565;cursor:pointer}
.huw-theatre-readout{white-space:nowrap;font-size:.8em}
.huw-pasteup-theatre-field{overflow:hidden;box-sizing:border-box;display:block}
.huw-pasteup-theatre-field>.tt-stretch{width:100%;height:100%}
.huw-pasteup-theatre-field .huw-theatre-player{max-height:100%;overflow:hidden}
.huw-theatre-stage .tt-pasteup-layout{margin:0!important;}
.huw-theatre-stage .tt-trackmouse{transition:none!important;transform-origin:center center}
.huw-theatre-curtain{width:100%;height:100%;background:repeating-linear-gradient(90deg,#933735 0,#b54e40 16px,#8d3432 32px);box-shadow:inset 0 -6px 12px #3b1318;pointer-events:none}
.huw-theatre-top{font-size:1.2em;line-height:1;color:#f9d894;text-align:center;font-weight:900;letter-spacing:.07em;text-shadow:2px 2px #592924}
.huw-theatre-footer{font-size:.65em;color:#ffdda0;text-align:center;letter-spacing:.15em;font-weight:800}
.huw-sky{width:100%;height:100%;background:linear-gradient(#b2daf6,#f8dfb7);}
.huw-sky-evening{width:100%;height:100%;background:linear-gradient(#35345f,#e88c72)}
.huw-hill{width:100%;height:100%;background:#65876b;border-radius:50% 50% 0 0}
.huw-hill-2{width:100%;height:100%;background:#426e5a;border-radius:50% 50% 0 0}
.huw-sun{width:100%;height:100%;background:#f7c45c;border-radius:50%;box-shadow:0 0 28px #fce09e}
.huw-cloud{width:100%;height:100%;background:#fdfafa;border-radius:60% / 70%;filter:drop-shadow(3px 5px 6px #4d5a663a)}
.huw-theatre-ground{width:100%;height:100%;background:#324d44}
.huw-theatre-caption{width:100%;height:100%;font-size:clamp(9px,1.7vw,24px);font-weight:900;color:#18374b;text-align:center;letter-spacing:.06em}
.huw-theatre-speech{background:#fff8e0;padding:3%;border:2px solid #3e6677;border-radius:14px;font-size:clamp(9px,1.55vw,20px);line-height:1.1;text-align:center;font-weight:800;box-shadow:2px 4px 10px #142a3933}
.huw-theatre-house{width:100%;height:100%;background:#d8a47b;border:5px solid #9d6552;clip-path:polygon(0 38%,50% 0,100% 38%,100% 100%,0 100%)}
.huw-pasteup-scene-animation{overflow:visible}
@media(prefers-reduced-motion:reduce){.huw-theatre-controls button{transition:none!important}}
