(function(){'use strict';var W=require('$:/core/modules/widgets/widget.js').widget,M=require('$:/plugins/huwiki/cutout/model.js');function Motion(p,o){this.initialise(p,o);}Motion.prototype=new W();Motion.prototype.render=function(parent,next){this.parentDomNode=parent;this.computeAttributes();var doc=this.document,self=this,title=this.getAttribute('tiddler'),data=M.read(this.wiki,title)||{},host=doc.createElement('section');host.className='co-studio';parent.insertBefore(host,next);this.domNodes.push(host);Object.keys(data).forEach(function(field){var h=doc.createElement('h3');h.textContent=field;host.appendChild(h);var table=doc.createElement('div');host.appendChild(table);function render(){table.textContent='';(data[field]||[]).forEach(function(k,index){var row=doc.createElement('div');row.className='co-actions';table.appendChild(row);[['t',coUi.t('Tid')],['dx','X %'],['dy','Y %'],['rotate','Rotation'],['scale',coUi.t('Skala')],['opacity',coUi.t('Synlighed')]].forEach(function(a){var label=doc.createElement('label');label.textContent=a[1];var input=doc.createElement('input');input.type='number';input.step='.01';input.style.width='80px';input.value=k[a[0]]===undefined?(a[0]==='scale'||a[0]==='opacity'?1:0):k[a[0]];input.onchange=function(){k[a[0]]=Number(input.value);};label.appendChild(input);row.appendChild(label);});var del=doc.createElement('button');del.textContent=coUi.t('Fjern');del.onclick=function(){data[field].splice(index,1);render();};row.appendChild(del);});}render();var add=doc.createElement('button');add.textContent=coUi.t('+ Nøglebillede');add.onclick=function(){data[field].push({t:0,dx:0,dy:0,rotate:0,scale:1,opacity:1});render();};host.appendChild(add);});var b=doc.createElement('button');b.textContent=coUi.t('Gem bevægelser');b.onclick=function(){Object.keys(data).forEach(function(k){data[k].sort(function(a,b){return a.t-b.t;});});self.wiki.addTiddler(new $tw.Tiddler(self.wiki.getTiddler(title),{title:title,type:'application/json',text:JSON.stringify(data,null,2)}));b.textContent=coUi.t('Gemt · gem også wikien');};host.appendChild(b);};Motion.prototype.refresh=function(changed){if(Object.keys(this.computeAttributes()).length){this.refreshSelf();return true;}return false;};exports['cutout-motion-editor']=Motion;})();
"},"$:/plugins/huwiki/theatre/Native/da/$:/plugins/huwiki/theatre/readme":{"title":"$:/plugins/huwiki/theatre/Native/da/$:/plugins/huwiki/theatre/readme","type":"text/vnd.tiddlywiki","text":"! HUWiki Teater
Let forestillingsafspiller, som kæder rigtige PasteUps sammen efter deres varighed.

Forestillings-tiddleren gemmer JSON med en ordnet liste af scener (`pasteup`, `duration`, valgfri `motion`). Brug widgetten `<$cutout-theatre tiddler="Teater – Min forestilling"/>`.

Hver scene er en selvstændig PasteUp. Dens `/Motion`-tiddler kan indeholde bevægelsesnøglebilleder pr. PasteUp-felt: `dx`, `dy` (procent), `rotate` (grader), `scale` og `opacity`. Disse bevægelser er ikke gemt i PasteUps oprindelige layout. CutOut-afspillere inde i scenerne følger teatrets tid.

Teaterpluginet kræver CutOut som afspilningsmotor. PasteUp er nødvendig for *denne* scenetype. HUWiki Slideshow er ikke et krav til Teater. Teater-eksemplerne er separat indhold.
"},"$:/plugins/huwiki/theatre/Native/en/$:/plugins/huwiki/theatre/readme":{"title":"$:/plugins/huwiki/theatre/Native/en/$:/plugins/huwiki/theatre/readme","type":"text/vnd.tiddlywiki","text":"! HUWiki Theatre

A lightweight player that sequences real PasteUp boards using their scene durations.

The performance tiddler stores JSON with an ordered list of scenes (`pasteup`, `duration`, optional `motion`). Use `<$cutout-theatre tiddler="Theatre – My performance"/>`.

Each scene is an independent PasteUp board. Its `/Motion` tiddler can contain keyframes per PasteUp field: `dx`, `dy` (percent), `rotate` (degrees), `scale` and `opacity`. These movements are separate from the original PasteUp layout. CutOut players inside scenes follow the performance timeline.

Theatre requires CutOut as its playback engine and PasteUp for this scene type. Slideshow is not required. Theatre examples are separate content.
"}}}
